const crypto = require('crypto');

const HMAC_SECRET   = $env['N8N_WEBHOOK_HMAC_SECRET'];
const MAX_SKEW_SECS = 300;

const item    = $input.first();
const headers = item.json.headers || {};

const sigHeader = headers['x-eduai-signature-256']   || '';
const tsHeader  = headers['x-eduai-timestamp']       || '';
const idempKey  = headers['x-eduai-idempotency-key'] || '';

const nowSecs = Math.floor(Date.now() / 1000);
const tsSecs  = parseInt(tsHeader, 10);
if (isNaN(tsSecs) || Math.abs(nowSecs - tsSecs) > MAX_SKEW_SECS) {
  throw new Error(`Timestamp rejected: skew=${nowSecs - tsSecs}s`);
}

const rawBody  = item.json.rawBody || JSON.stringify(item.json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', HMAC_SECRET).update(rawBody, 'utf8').digest('hex');
const sigBuf = Buffer.from(sigHeader);
const expBuf = Buffer.from(expected);
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('Signature verification failed');
}

const body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
return [{ json: { ...body, _idempotency_key: idempKey, _verified: true } }];

// ── Deliverable 2: Role Isolation ──────────────────────────────────────────
// File-upload events are only valid for student and professor actors.
// Admin accounts do not submit assignments; system events use a different path.
const ALLOWED_ROLES = ['student', 'professor'];

const item = $input.first();
const role = (item.json.payload || {}).role || '';

if (!ALLOWED_ROLES.includes(role)) {
  console.error(JSON.stringify({
    level: 'error', message: 'role_rejected',
    role, allowed: ALLOWED_ROLES,
    event_id: item.json.event_id,
  }));
  throw new Error(`Role '${role}' is not permitted in the file-upload workflow. Allowed: ${ALLOWED_ROLES.join(', ')}`);
}

return [{ json: { ...item.json, _role_validated: true } }];

// Merge the idempotency API response with the full verified payload.
// Fail-open: if backend was unreachable ($input has an error object),
// treat the event as fresh so processing is never silently dropped.
const verified  = $('Validate Role').item.json;
const idempResp = $input.first().json;

// idempResp.fresh === false  → duplicate (already processed)
// idempResp.fresh === true   → new event
// idempResp.error exists     → Redis/backend unreachable → fail-open → treat as new
const isDuplicate = idempResp.fresh === false && !idempResp.error;

if (isDuplicate) {
  console.log(JSON.stringify({
    level: 'info', message: 'event_duplicate_skipped',
    event_id: verified.event_id,
    idempotency_key: verified._idempotency_key,
  }));
} else if (idempResp.error) {
  console.warn(JSON.stringify({
    level: 'warn', message: 'idempotency_backend_unreachable_fail_open',
    event_id: verified.event_id,
    error: String(idempResp.error).slice(0, 200),
  }));
}

return [{ json: { ...verified, _is_duplicate: isDuplicate } }];

// ── Deliverable 4: Structured event log ────────────────────────────────────
const item    = $input.first();
const payload = item.json.payload || {};

console.log(JSON.stringify({
  level:          'info',
  message:        'file_upload_event_processed',
  event_id:       item.json.event_id,
  event_type:     item.json.event_type,
  correlation_id: item.json.correlation_id,
  file_id:        payload.file_id,
  user_id:        payload.user_id,
  role:           payload.role,
  file_type:      payload.file_type,
  file_size_bytes: payload.file_size_bytes,
  timestamp:      new Date().toISOString(),
}));

return [{ json: { ...item.json, _processed_at: new Date().toISOString() } }];
